function RegressionTaskDialog:SetDayIndex(index)
    local oldIndex = self:GetDayIndex()
    self.selectedDayIndex_ = checkInt(index)
    if self:GetDayIndex() == oldIndex then
        return
    end
    -- refresh node
    local oldNode = self.LayoutDayGroup:Find("BtnDay" .. oldIndex)
    if oldNode then
        ---@type RegressionTaskDayNode
        local env = CfUtils.GetLuaScr(oldNode, "Game.UI.Regression.RegressionTaskDayNode")
        env:FreshSelectStatus(false)
    end

    local node = self.LayoutDayGroup:Find("BtnDay" .. self:GetDayIndex())
    if node then
        ---@type RegressionTaskDayNode
        local env = CfUtils.GetLuaScr(node, "Game.UI.Regression.RegressionTaskDayNode")
        env:FreshSelectStatus(true)
    end

    -- refresh list
    if not self.ListView.IsListViewInit then
        self.ListView:InitListView(self:GetTaskNum(), Bind(self, self.OnGetTaskItem))
        self.ListView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.ListView, self:GetTaskNum())
    end
end
