local DEBUG_AN = false

function RegressionTaskDialog:SetPoint(point, index)
    if DEBUG_AN then
        self:GetRegressDt().point =  self:GetRegressDt().point + checkInt(point)
    else
        self:GetRegressDt().point = checkInt(point)
    end
    ---@param boxData {id : integer, desc: string, unlockPoint : string, reward : table, status : integer}
    for _, boxData in ipairs(self:GetRegressDt().taskBox) do
        if checkInt(boxData.unlockPoint) > self:GetPoint() then
            break
        elseif checkInt(boxData.status) == Constants.GetStatus.Not then
            boxData.status = Constants.GetStatus.Can
        end
    end
    self:UpdateActivityRedPoint()
    if checkNumber(index) > 0 then
        CfUtils.StartCoroutineWithBlocker(function()
            xTry(function()
                local cellNode = self.ListView:GetShownItemByIndex(index - 1)
                local moveTrans = cellNode.transform:Find("UIFX_Number_BoomMove")
                ---@type UnityEngine.RectTransform
                --local rectTransform = KTool.GetComponent(moveTrans.gameObject, typeof(RectTransform))
                --local position = rectTransform.anchoredPosition
                local position = moveTrans.position
                ---@type UnityEngine.RectTransform
                --local rectTargetTransform = KTool.GetComponent(self.UIFX_MoveBoom.gameObject, typeof(RectTransform))
                --local targetPosition = rectTargetTransform.anchoredPosition
                local isFlying = true
                CfUtils.SetActive(moveTrans, true)
                moveTrans.transform:DOMove(self.UIFX_MoveBoom.transform.position, TIME_OF_ARRANGE):OnComplete(function()
                    isFlying = false
                end)
                while isFlying do
                    coroutine.yield()
                end
                CfUtils.SetActive(self.UIFX_MoveBoom, true)
                moveTrans.position = position
                ---还原位置点
                --rectTransform.anchoredPosition = position
                CfUtils.SetActive(moveTrans, false)
                CoYield(TIME_OF_ARRANGE)
                CfUtils.FillText(self.TxtNumCount, self:GetPoint())
                CfUtils.SetActive(self.UIFX_MoveBoom, false)
                CfUtils.SetActive(self.UIFX_BoxUpgrade, true)
                CoYield(TIME_OF_ARRANGE)
                CfUtils.SetActive(self.UIFX_BoxUpgrade, false)
                local finalBox = self:GetRewardDtByIndex(self:GetRewardNum())
                if finalBox then
                    CfUtils.SetSliderPercent(self.Slider, self:GetSliderPoint())
                end
                self:FreshBoxNode()
            end)
        end)
    else
        CfUtils.FillText(self.TxtNumCount, self:GetPoint())
    end
end
