function RegressionTaskDialog:CheckIsTaskEnd()
    if self.activityDojo.endTime - os.time() <= 0 then
        GameUtils.Toast(localize("回归任务已结束"))
        return true
    end
    return false
end

function RegressionTaskDialog:InitData()
    self.rewardInitIndex = self:GetRewardNum()
    for index = 1, self:GetRewardNum() do
        local rewardDt = self:GetRewardDtByIndex(index)
        if checkInt(rewardDt.status) ~= Constants.GetStatus.Has then
            self.rewardInitIndex = index
            break
        end
    end

    self.dayTaskMap = {}
    for _, taskDt in ipairs(self:GetRegressDt().task) do
        local day = checkInt(taskDt.unlockDayNum)
        if not self.dayTaskMap[day] then
            self.dayTaskMap[day] = {}
        end

        -- 奖励中加入经验显示
        if checkInt(taskDt.exp) > 0 then
            if taskDt.rewards[#taskDt.rewards].goodsId ~= playerGoodsExp then
                table.insert(taskDt.rewards, { goodsId = playerGoodsExp, num = checkInt(taskDt.exp) })
            end
        end

        table.insert(self.dayTaskMap[day], taskDt)
    end

    for _, dayTaskDt in ipairs(self.dayTaskMap) do
        table.sort(dayTaskDt, function(task1, task2)
            if checkInt(task1.status) ~= checkInt(task2.status) then
                if checkInt(task1.status) == Constants.GetStatus.Can or checkInt(task2.status) == Constants.GetStatus.Can then
                    return checkInt(task1.status) == Constants.GetStatus.Can
                else
                    return checkInt(task1.status) < checkInt(task2.status)
                end
            else
                return checkInt(task1.id) < checkInt(task2.id)
            end
        end)
    end

end

