function RegressionTaskDialog:FreshBoxNode()
    KTool.DestroyGameObjectChildren(self.RewardList.gameObject, false)
    local rewardNum = checkNumber(self:GetRewardNum())
    for index = 1, rewardNum do
        local go = CfUtils.InstantiateGo(self.RewardNode.gameObject, self.RewardList.gameObject)
        go.name = "RewardNode" .. index
        CfUtils.SetActive(go, true)
        ---@type RegressionTaskRewardNode
        local env = CfUtils.GetLuaScr(go, "Game.UI.Regression.RegressionTaskRewardNode")
        if env then
            env:UpdateSelf(self:GetRewardDtByIndex(index), index, index == self:GetRewardNum())
            env:SetBtnCB(Bind(self, self.OnClickRewardBtnHandler_))
        end
    end
end

function RegressionTaskDialog:GetSliderPoint()
    local finalBox = self:GetRewardDtByIndex(self:GetRewardNum())
    local point =  math.min(checkNumber(self.regressDt_.point) / checkNumber(finalBox.unlockPoint), 1)
    if point <= 0.1 then
        point = point * 1.5
    elseif point <= 0.2 then
        point = (point -0.1)  * 2 + 0.15
    elseif point > 0.2 and point <= 0.6 then
        point = point + 0.18
    else 
        point = 0.8 + (point - 0.6)/2
    end
    return math.min(point , 1)
end
