function RegressionTaskDialog:RefreshDayView()
    self.totalTaskRedCount = 0
    KTool.DestroyGameObjectChildren(self.LayoutDayGroup.gameObject, false)
    for index = 1, self:GetAllDayNum() do
        local node = CfUtils.InstantiateGo(self.BtnDayNode.gameObject, self.LayoutDayGroup.gameObject)
        if node then
            CfUtils.SetActive(node, true)
            node.name = "BtnDay" .. index
            SetButtonAction(node, function()
                if index > self:GetRegressDt().todayNum then
                    GameUtils.Toast(localize("该任务暂未开放"))
                else
                    self:SetDayIndex(index)
                end
            end)
        end

        local progress = 0
        local redCount = 0
        if self:GetRegressDt().todayNum >= index then
            for _, taskDt in ipairs(self:GetDayTasksByDayIndex(index)) do
                if checkInt(taskDt.status) == Constants.GetStatus.Has then
                    progress = progress + 1
                elseif checkInt(taskDt.status) == Constants.GetStatus.Can then
                    redCount = redCount + 1
                    self.totalTaskRedCount = self.totalTaskRedCount + 1
                end
            end
        end

        local data = {
            progress = progress,
            count = self:GetTaskNum(index),
            day = index,
            redCount = redCount,
            isOpened = index <= self:GetRegressDt().todayNum,
        }

        ---@type RegressionTaskDayNode
        local env = CfUtils.GetLuaScr(node.gameObject, "Game.UI.Regression.RegressionTaskDayNode")
        if env then
            env:FreshBaseUI(data, self:GetRegressDt().todayNum, self:GetDayIndex() == index)
            env:UpdateRedPointStatus()
        end
    end
end

