function RegressionTaskDialog:OnClickRewardBtnHandler_(cellData, index)
    if self:CheckIsTaskEnd() then
        return
    end
    if checkInt(cellData.status) == Constants.GetStatus.Has then
        -- local node = self.RewardList.transform:GetChild(index - 1)
        -- GameUtils.ShowCommonTipsBoardRewardPreview(node, cellData.rewards, localize('奖励预览:'), false)
        GameUtils.Toast(localize('当前奖励已领取'))
        return
    end
    if checkNumber(self.regressDt_.point) < checkNumber(cellData.unlockPoint) then
        local node = self.RewardList.transform:GetChild(index - 1)
        GameUtils.ShowCommonTipsBoardRewardPreview(node, cellData.rewards, localize('奖励预览:'), false)
        -- GameUtils.Toast(localize('当前积分不足'))
        return
    end
    GameUtils.Request(Interfaces.RegressTaskBoxDraw, { rewardId = cellData.id, type = self:GetRegressConf().type }, function(request, response)
        if checkInt(response.errCode) == 0 then
            for _, taskDt in ipairs(self:GetRegressDt().taskBox) do
                if checkInt(taskDt.id) == checkInt(cellData.id) then
                    taskDt.status = Constants.GetStatus.Has
                    break
                end
            end

            GoodsUtils.DrawRewards(response.data.rewards, true)
            UIModule.OpenDialog(
                    {
                        id = Constants.UITypeIds.UICommonRewardPop,
                        parameters = { rewards = response.data.rewards }
                    }
            )

            local node = self.RewardList.transform:GetChild(index - 1)
            if node then
                ---@type RegressionTaskRewardNode
                local env = CfUtils.GetLuaScr(node, "Game.UI.Regression.RegressionTaskRewardNode")
                if env then
                    env:UpdateStatus()
                end
            end

            self:UpdateActivityRedPoint()
        end
    end)
end

function RegressionTaskDialog:HasUnclaimedTask()
    for k, v in pairs(self.dayTaskMap) do
        for i, b in pairs(v) do
            local isOpened = k <= self:GetRegressDt().todayNum
            if isOpened then
                if checkNumber(b.status) == Constants.GetStatus.Can then
                    return true
                end
            end
        end
    end
    return false
end

function RegressionTaskDialog:OnClickAutoGetTaskBtn()
    if self:CheckIsTaskEnd() then
        return
    end
    if self:HasUnclaimedTask() then
        --print("11----------"..table.dump(self:GetRegressDt().task, nil, 3))
        --print("@@----------"..table.dump(self.dayTaskMap, nil, 3))

        local task = clone(self:GetRegressDt().task)
        for i, v in pairs(task) do
            local isOpened = v.unlockDayNum <= self:GetRegressDt().todayNum
            if isOpened then
                if checkNumber(v.status) == Constants.GetStatus.Can then
                    self:GetRegressDt().task[i]["status"] = Constants.GetStatus.Has
                end
            end
        end
        --print("22----------"..table.dump(self:GetRegressDt().task, nil, 3))
        --print("@@----------"..table.dump(self.dayTaskMap, nil, 3))


        GameUtils.Request(Interfaces.RegressTaskDraw, { id = nil, type = self:GetRegressConf().type }, function(request, response)
            if checkInt(response.errCode) == 0 then
                --region 数据维护


                self:GetRegressDt().point = checkInt(response.data.point)
                --endregion
                -- update goodsNum
                GoodsUtils.DrawRewards(response.data.rewards, true)

                -- update exp
                local showRewards = response.data.rewards
                if response.data.playerLv ~= nil and response.data.mainExp ~= nil then
                    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                    playerComponent:UpdatePlayerLvMainExp(response.data.playerLv, response.data.mainExp, response.data.hp)
                    local playerExpGoodNum = playerComponent.playerDojo.mainExp - playerComponent:GetExpBefore()
                    if playerExpGoodNum > 0 then
                        table.insert(showRewards, { goodsId = playerGoodsExp, num = playerExpGoodNum })
                    end
                end

                -- show rewards
                UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = showRewards }
                        }
                )

                self:FreshBaseUI()
                self:RefreshAllShownItem(self.ListView)
                self:RefreshAllShownItem(self.RewardList)
            end


        end)

    end
end

function RegressionTaskDialog:RefreshAllShownItem(nodeTrans)
    local listView = KTool.GetComponent(nodeTrans.gameObject, typeof(CS.SuperScrollView.LoopListView2))
    if not isNull(listView) then
        listView:RefreshAllShownItem()
    end
end

function RegressionTaskDialog:OnClickTaskBtnHandler_(cellData, status, openType, index)
    if self:CheckIsTaskEnd() then
        return
    end

    if checkInt(status) == Constants.GetStatus.Can then
        GameUtils.Request(Interfaces.RegressTaskDraw, { id = cellData.id, type = self:GetRegressConf().type }, function(request, response)
            if checkInt(response.errCode) == 0 then
                local data = self:GetDayTasksByDayIndex()[index]
                data.status = Constants.GetStatus.Has

                -- update goodsNum
                GoodsUtils.DrawRewards(response.data.rewards, true)

                -- update exp
                local showRewards = response.data.rewards
                if response.data.playerLv ~= nil and response.data.mainExp ~= nil then
                    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                    playerComponent:UpdatePlayerLvMainExp(response.data.playerLv, response.data.mainExp, response.data.hp)
                    local playerExpGoodNum = playerComponent.playerDojo.mainExp - playerComponent:GetExpBefore()
                    if playerExpGoodNum > 0 then
                        table.insert(showRewards, { goodsId = playerGoodsExp, num = playerExpGoodNum })
                    end
                end

                -- show rewards
                UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = showRewards }
                        }
                )

                -- update view
                local node = self.ListView:GetShownItemByItemIndex(index - 1)
                if node then
                    local env = CfUtils.GetLuaScr(node, "Game.UI.Regression.RegressionTaskContentNode")
                    if env then
                        env:UpdateStatus()
                    end
                end

                local node = self.LayoutDayGroup.transform:Find("BtnDay" .. self:GetDayIndex())
                if node then
                    ---@type RegressionTaskDayNode
                    local env = CfUtils.GetLuaScr(node, "Game.UI.Regression.RegressionTaskDayNode")
                    env:AddProgress(1)
                    env:DelRedCount(1)
                    env:FreshSelectStatus(true)
                    env:UpdateRedPointStatus()
                end

                self.totalTaskRedCount = self.totalTaskRedCount - 1

                -- calculate point
                self:SetPoint(response.data.point, index)

                -- update reward status
                self:RefreshAllShownItem(self.RewardList)
            end


        end)
    elseif checkInt(status) == Constants.GetStatus.Not then
        if DEBUG_AN then
            ---测试播领取动画
            self:SetPoint(cellData.point, index)
        else
            if checkInt(openType) > 0 then
                local goodsConfMgr = GoodsConfMgr:GetInstance()
                goodsConfMgr:ExecuteJump(goodsConfMgr:GetJumpModuleRow(openType), {}, 0, false)
                KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self:GetRegressConf().id)
            end
        end
    end
end

function RegressionTaskDialog:UpdateActivityRedPoint()
    local hasRed = self.totalTaskRedCount > 0
    if not hasRed then
        for _, pointDt in ipairs(self:GetRegressDt().taskBox) do
            if checkInt(pointDt.status) == Constants.GetStatus.Can then
                hasRed = true
                break
            end
        end
    end
    if not hasRed then
        if isNotNull(self:GetRegressDt().regressMallRedDotHint) and checkInt(self:GetRegressDt().regressMallRedDotHint) == 0 then
            hasRed = true
        end 
    end
    ActivityUtils.UpdateActivityMainRedPointState(self:GetRegressConf().id, hasRed and 0 or -1)
end

