    if env then
        if self:GetTaskItemShowNum() <= 0 then
            local cellSizeH = cell.CachedRectTransform.rect.height + cell.Padding
            self.taskItemShowNum_ = math.ceil(listView.ViewPortHeight / cellSizeH)
        end
        local cellData = self:GetTaskDtByIndex(index)
        env:RefreshSelf(cellData, index)
        env:SetBtnCB(Bind(self, self.OnClickTaskBtnHandler_))
        local isCanDraw = checkNumber(cellData.status) == Constants.GetStatus.Can
        if isCanDraw and not self.cellCanDrawAnimMap_[tostring(cellData.id)] then
            env:PlayCompleteAnim()
            self.cellCanDrawAnimMap_[tostring(cellData.id)] = true
        end
    end

    return cell
end

return RegressionTaskDialog